def compute(vars):
    illumina_index = vars["v1"]
    nasdaq_pharma_index = vars["v2"]
    difference = illumina_index - nasdaq_pharma_index
    return {
        "value": difference,
        "trace": {
            "illumina_index": illumina_index,
            "nasdaq_pharma_index": nasdaq_pharma_index,
            "difference_percentage_points": difference,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
